var count1 = 700;
var count2 = 70;

var spacing = 6;
var repulsionRadius = 100;
var particlesA = [];
var particlesB = [];

var pause = false;

function setup() {
  createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 255);

	for (let i = 0; i < count1; i++) {
		let angle = i * 137.5;
		let r = spacing * sqrt(i);
		let x = r * cos(radians(angle)) + width / 2;
		let y = r * sin(radians(angle)) + height / 2;
		let distToCenter = dist(x, y, width / 2, height / 2);
		let s = 255 - distToCenter * 1.25;
		let b = 150 + distToCenter * 1;
		let color = 160;

		particlesA.push(new Particle(
			random(width), -200, 
			x, y, 
			0.5,
			s,b,color));
	}


	for (let i = 0; i < count2; i++) {
		var angle = i * 137.5;
		var r = spacing * sqrt(i);
		var x = r * cos(radians(angle)) + width / 2;
		var y = r * sin(radians(angle)) + height / 2;
		var distToCenter = dist(x, y, width / 2, height / 2);
		var s = 255 - distToCenter * 1.25;
		var b = 150 + distToCenter * 1;
		var color = 255;

		particlesB.push(new Particle(
			random(width), -200, 
			x, y, 
			0.5,
			s,b,color));
	}
} 

function draw() {
  background(50,50,50);


	for (let i = 0; i < particlesA.length; i++) {
		!pause && particlesA[i].move();
		particlesA[i].display();
	}
		for (let i = 0; i < particlesB.length; i++) {
		!pause && particlesB[i].move();
		particlesB[i].display();
	}


	stroke(0, 50);
	strokeWeight(repulsionRadius * 2);
	point((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function mouseClicked() {
  return pause = !pause;
}


// === Tab: particle.js ===
function Particle(x, y, targetX, targetY, maxForce, s, b, color) {

  this.pos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);
	this.target = new p5.Vector(targetX, targetY);
  this.maxForce = maxForce * random(0.8, 1.2);

	this.sat = s;
	this.bright = b;
	this.color = color;

  this.move = function() {
    let distThreshold = 20;

    let steer = new p5.Vector(this.target.x, this.target.y);
    let distance = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
		if (distance > 0.5) {
			steer.sub(this.pos);
			steer.normalize();
			steer.mult(map(min(distance, distThreshold), 0, distThreshold, 0, this.maxForce));
			this.acc.add(steer);
		}

		let mouseDistance = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		if (mouseDistance < repulsionRadius) {
			let repulse = new p5.Vector(this.pos.x, this.pos.y);
			repulse.sub((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
			repulse.mult(map(mouseDistance, 100, 0, 0, 0.5));
			this.acc.add(repulse);
		}

    this.vel.mult(0.95);

    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  this.display = function() {
    strokeWeight(1);
    stroke(0, 100);
    line(this.target.x, this.target.y, this.pos.x, this.pos.y);

    strokeWeight(6);
    stroke(color, this.sat, this.bright);
    point(this.pos.x, this.pos.y);
  }
}

